using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 string communitySelection="";
 void ShowCommunity(string selected=""){Community.Seed(game.World);if(selected!="")communitySelection=selected;var box=Panel("CAMP / SURVIVOR COMMUNITY");coopMenu="community";Button(box,"PEOPLE / PERSONAL REPUTATION",ShowRelationships);Button(box,"YOUR DOG / CARE AND COMMANDS",ShowDog);Button(box,"THE WATERLINE / NEIGHBORING COMMUNITIES",ShowWorldLedger);int members=Community.Survivors.Count(n=>n.Member);Text(box,$"{members}/3 residents / FOOD {Community.Food} / WATER {Community.Water} / AMMO {Community.Ammo} / TIMBER {Community.Stock[0]} / FIBER {Community.Stock[2]}\n"+(Community.Established?$"Camp {(int)Community.X}, {(int)Community.Z} / transfers require being within 20m":"Recruit your first rescued survivor beside a sheltered cot to establish camp."));
  var scroll=new ScrollContainer{CustomMinimumSize=new(880,400)};box.AddChild(scroll);var content=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(content);foreach(var person in Community.Survivors){var copy=person;string status=person.Member?(!string.IsNullOrEmpty(person.Owner)?"COMPANION":person.Job.ToUpperInvariant()):person.State.ToUpperInvariant();Button(content,$"{person.Name} / {status} / health {person.Health:0} / morale {person.Morale:0} / injury {person.Injury:0}",()=>ShowCommunity(copy.Id));}
  var n=Community.Survivors.FirstOrDefault(s=>s.Id==communitySelection)??Community.Survivors.First();communitySelection=n.Id;Text(content,n.Name+" / "+(n.Member?"Shelter: "+(ExpeditionCommunity.Sheltered(Community.Bed(n,game.Building.Pieces),game.Building.Pieces)?"ready":"missing cot, roof or walls"):$"Rescue location: {(int)RescuePoint(n).X}, {(int)RescuePoint(n).Z}"));
  var grid=new GridContainer{Columns=3};content.AddChild(grid);void Action(string title,string operation){var b=new Godot.Button{Text=title,CustomMinimumSize=new(280,36)};grid.AddChild(b);b.Pressed+=()=>{if(!CoopRequest("community",n.Id+"|"+operation))CommunityAction(n.Id+"|"+operation);ShowCommunity(n.Id);};}
  if(n.State=="trapped"){Text(content,"Clear the infected, then talk beside the survivor. They will follow you back to camp.");Action("RESCUE SURVIVOR","rescue");}
  else if(!n.Member){Text(content,Community.RecruitReason(n,game,player.Position.X,player.Position.Z)+" / each resident needs a separate survivor cot, a roof, two walls and three food portions.");Action("RECRUIT / 3 FOOD","recruit");Action("FOLLOW ME TO CAMP","escort");Action("FIRST AID / 1 BANDAGE","aid");}
  else{Action("ASSIGN FREE SHELTERED COT","bed");Action("COLLECT DEADWOOD","wood");Action("TEND SUPPLIES","supplies");Action("GUARD CAMP","guard");Action("COME WITH ME","follow");Action("RETURN TO CAMP JOB","stay");Action("FIRST AID / 1 BANDAGE","aid");}
  if(Community.Established){var supplies=new GridContainer{Columns=3};content.AddChild(supplies);foreach(var transfer in new[]{("ADD 3 FOOD","deposit-food"),("ADD 3 WATER","deposit-water"),("ADD 3 FIBER","deposit-fiber"),("ADD 12 AMMO","deposit-ammo"),("TAKE 5 TIMBER","take-wood")}){var copy=transfer;var button=new Godot.Button{Text=copy.Item1,CustomMinimumSize=new(280,34)};supplies.AddChild(button);button.Pressed+=()=>{if(!CoopRequest("community",n.Id+"|"+copy.Item2))CommunityAction(n.Id+"|"+copy.Item2);ShowCommunity(n.Id);};}}
  Text(content,"Workers need food and shelter. Deadwood: 2 timber per 2 work minutes. Supplies: 1 water + 1 fiber becomes 2 food per 3 work minutes. Low morale slows work; serious injuries pause jobs. Guards and your one companion use shared ammunition, then fight in melee. No offline production.");Text(content,"Downed survivors can receive first aid; after 90 active seconds they recover at camp with serious injuries. They need food and shelter to recuperate. Companions wait outside dungeons.");Text(box,game.Notice);Button(box,"BACK",CloseMenu);
 }
}
